        if d["week"] != wk: continue
        md.append("**%s %s.%s. %s** (%s)" % (d["day"], d["date"][8:], d["date"][5:7], d["session"], d["status"]))
        if d["session"].startswith("Rest") and d["date"] not in NOTES: md += ["", "- Goal: %s." % d["goal"], ""]; continue
